NULL DEFAULT (datetime('now'))); CREATE INDEX IF NOT EXISTS idx_vevents_visitor ON visitor_events(visitor_id); CREATE INDEX IF NOT EXISTS idx_vevents_kind ON visitor_events(kind, ref); CREATE TABLE IF NOT EXISTS library_files (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, track TEXT NOT NULL DEFAULT 'accounting', subcat TEXT, audiences TEXT NOT NULL DEFAULT 'accountant', access TEXT NOT NULL DEFAULT 'free' CHECK (access IN ('free','paid','course')), price REAL NOT NULL DEFAULT 0, course_id INTEGER REFERENCES courses(id) ON DELETE SET NULL, related_course_id INTEGER REFERENCES courses(id) ON DELETE SET NULL, file_name TEXT, mime TEXT, size INTEGER NOT NULL DEFAULT 0, chunks INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, visible INTEGER NOT NULL DEFAULT 1, sort INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT); CREATE TABLE IF NOT EXISTS library_grants (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, file_id INTEGER NOT NULL REFERENCES library_files(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY (user_id, file_id)); CREATE TABLE IF NOT EXISTS activation_tokens (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, used_at TEXT); UPDATE settings SET value = 'IK Academy' WHERE key IN ('brand_name', 'footer_line1') AND value = 'Mr. Islam Khalifa | Accounting'; INSERT OR IGNORE INTO settings (key, value) VALUES ('brand_by', 'by Mr. Islam Khalifa'); INSERT OR IGNORE INTO settings (key, value) VALUES ('tracks', 'accounting | المحاسبة والضرائب | من أول قيد لحد القوائم المالية والضرايب، بالقصة والتطبيق' || char(10) || 'business | إدارة المشروعات الصغيرة | افهم أرقام شغلك: التسعير، والكاش، والربح الحقيقي' || char(10) || 'hr | الموارد البشرية وشؤون العاملين | المرتبات والتأمينات وملفات العاملين صح من أول مرة'); INSERT OR IGNORE INTO settings (key, value) VALUES